    product: MOCK_LINE_ITEM,
    primaryAction: <button type="button">Remove</button>,
  },
};

export const MultipleItems: Story = {
  render: (args) => (
    <>
      <ProductItem {...args} product={MOCK_LINE_ITEM} primaryAction={<button type="button">Remove</button>} />
      <ProductItem {...args} product={MOCK_LINE_ITEM_TWO} primaryAction={<button type="button">Remove</button>} />
    </>
  ),
};

// See this file's own docblock: demonstrates the `hideStepperAndActions` capability only, not
// real gift-card detection. `primaryAction`/`secondaryActions`/`deliveryActions` are still passed
// here deliberately, to prove they are suppressed by the prop rather than merely absent.
export const GiftCard: Story = {
  args: {
    product: MOCK_LINE_ITEM,
    primaryAction: <button type="button">Remove</button>,
    secondaryActions: <button type="button">Edit</button>,
    hideStepperAndActions: true,
  },
};

/**
 * SFCC-795 (plan step 3.2): `message` renders `ZimmInlineMessage` between the stepper and the
 * actions row, and — the one thing no Vitest test can see, since jsdom does not evaluate
 * `@media` rules — the Item Details gap actually widens 12px -> 16px when the message's variant
 * is `error`. This story is the only place that visual effect is provable at all.
 */
export const WithErrorMessage: Story = {
  args: {
    product: MOCK_LINE_ITEM,
    primaryAction: <button type="button">Remove</button>,
    secondaryActions: <button type="button">Edit</button>,
    message: { variant: 'error', text: 'Quantity unavailable in this size' },
  },
};

/** Warning variant — max-quantity messaging. Gap stays at the default 12px (only `error` widens it). */
export const WithWarningMessage: Story = {
  args: {
    product: MOCK_LINE_ITEM,
    primaryAction: <button type="button">Remove</button>,
    secondaryActions: <button type="button">Edit</button>,
    message: { variant: 'warning', text: 'Maximum purchase quantity reached for this size' },
  },
};

/**
 * SFCC-795 (plan step 3.3): `discountLabel` renders directly beneath the stepper/price row,
 * ahead of any `message` — see index.tsx's own docblock and this prop's JSDoc for the DOM-order
 * reasoning. Styling: renders via `ZimmInlineMessage variant="success"` (green `status.success`,
 * regular weight, no icon) per Marcel's direct Figma inspector pull for this exact node
 * (2026-09-18) — corrected from an earlier, wrong guess (`text-secondary` grey, no Figma citation
 * at all). Combined with a warning `message` here specifically to prove both slots coexist in the
 * correct order, not just individually.
 */
export const WithDiscountLabel: Story = {
  args: {
    product: MOCK_LINE_ITEM,
    primaryAction: <button type="button">Remove</button>,
    secondaryActions: <button type="button">Edit</button>,
    discountLabel: '20% off applied',
    message: { variant: 'warning', text: 'Maximum purchase quantity reached for this size' },
  },
};

