// Live browser a11y measurement script for SFCC-795 accessibility sweep.
// Uses the Playwright LIBRARY API directly against the already-running Storybook dev server.
// Does NOT use `npx playwright test` and does NOT touch playwright.config.*
'use strict';
const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright');

const BASE = 'http://localhost:6006/iframe.html';
const iframeUrl = (id) => `${BASE}?id=${id}&viewMode=story`;

const STYLE_PROPS = ['outline', 'outlineOffset', 'outlineColor', 'outlineStyle', 'outlineWidth', 'boxShadow'];

function log(section, obj) {
  console.log(`\n----- ${section} -----`);
  if (typeof obj === 'string') console.log(obj);
  else console.log(JSON.stringify(obj, null, 2));
}

async function waitForStorybookRoot(page, timeout = 15000) {
  await page.waitForFunction(
    () => {
      const root = document.querySelector('#storybook-root');
      return !!root && root.children.length > 0;
    },
    { timeout }
  );
  await page.waitForTimeout(300);
}

async function waitForDialog(page, timeout = 15000) {
  await page.waitForSelector('[role="dialog"]', { timeout });
  await page.waitForTimeout(300);
}

// Simplified accessible-name / role computation for whatever is currently focused.
// Not the full W3C accname algorithm, but covers aria-label / aria-labelledby / <label> /
// alt / placeholder / textContent, which is everything this component set actually uses.
async function getFocusedInfo(page) {
  return page.evaluate(() => {
    function computeName(el) {
      if (!el) return null;
      const ariaLabel = el.getAttribute && el.getAttribute('aria-label');
      if (ariaLabel && ariaLabel.trim()) return ariaLabel.trim();
      const labelledby = el.getAttribute && el.getAttribute('aria-labelledby');
      if (labelledby) {
        const ids = labelledby.split(/\s+/);
        const text = ids
          .map((id) => {
            const e = document.getElementById(id);
            return e ? e.textContent.trim() : '';
          })
          .join(' ')
          .trim();
        if (text) return text;
      }
      if (el.id) {
        const label = document.querySelector('label[for="' + el.id.replace(/"/g, '\\"') + '"]');
        if (label && label.textContent.trim()) return label.textContent.trim();
      }
      const closestLabel = el.closest && el.closest('label');
      if (closestLabel && closestLabel.textContent.trim()) return closestLabel.textContent.trim();
      if (el.tagName === 'IMG') {
        const alt = el.getAttribute('alt');
        if (alt !== null) return alt.trim();
      }
      if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') {
        const ph = el.getAttribute('placeholder');
        if (ph && ph.trim()) return ph.trim();
      }
      const text = el.textContent ? el.textContent.trim().replace(/\s+/g, ' ') : '';
      if (text) return text;
      const title = el.getAttribute && el.getAttribute('title');
      if (title && title.trim()) return title.trim();
      return null;
    }
    function computeRole(el) {
      if (!el) return null;
      const explicit = el.getAttribute && el.getAttribute('role');
      if (explicit) return explicit;
      const tag = el.tagName;
      if (tag === 'BUTTON') return 'button';
      if (tag === 'A' && el.hasAttribute('href')) return 'link';
      if (tag === 'INPUT') {
        const type = (el.getAttribute('type') || 'text').toLowerCase();
        if (type === 'number') return '(native input[type=number], no explicit role attr)';
        if (type === 'checkbox') return 'checkbox';
        if (type === 'radio') return 'radio';
        return 'textbox';
      }
      if (tag === 'TEXTAREA') return 'textbox';
      if (tag === 'SELECT') return 'combobox';
      return null;
    }
    const el = document.activeElement;
    if (!el || el === document.body) {
      return { tag: 'BODY', role: null, name: null, isBody: true };
    }
    return {
      tag: el.tagName,
      role: computeRole(el),
      name: computeName(el),
      id: el.id || null,
      type: el.getAttribute ? el.getAttribute('type') : null,
      value: 'value' in el ? el.value : null,
      disabled: 'disabled' in el ? el.disabled : null,
      ariaDisabled: el.getAttribute ? el.getAttribute('aria-disabled') : null,
      outerHTMLSnippet: el.outerHTML ? el.outerHTML.slice(0, 200) : null,
    };
  });
}

async function getActiveElementStyle(page) {
  return page.evaluate((props) => {
    const el = document.activeElement;
    if (!el || el === document.body) return null;
    const cs = window.getComputedStyle(el);
    const out = {};
    for (const p of props) out[p] = cs[p];
    return out;
  }, STYLE_PROPS);
}

async function getLocatorStyle(locator) {
  return locator.evaluate((el, props) => {
    const cs = window.getComputedStyle(el);
    const out = {};
    for (const p of props) out[p] = cs[p];
    return out;
  }, STYLE_PROPS);
}

async function main() {
  const browser = await chromium.launch({ headless: true });
  const results = {};

  try {
    // =====================================================================
    // TASK 1 — Real ProductItem Tab walkthrough (WithWarningMessage)
    // =====================================================================
    try {
