        incrementAccessibleName: incCount ? await incLocator.first().evaluate((el) => el.getAttribute('aria-label')) : null,
        decrementAccessibleName: decCount ? await decLocator.first().evaluate((el) => el.getAttribute('aria-label')) : null,
