        status: await statusLocator.first().evaluate((el) => el.textContent),
      });

      const beforeIncrement = await readState();
      // Click the increment button directly by role (mouse click this time, to isolate from
      // keyboard-path timing) and sample the live region at several delays.
      const incButton = page.getByRole('button', { name: /Increment Quantity/i });
      await incButton.click();
      const samples = [];
      for (const delay of [0, 100, 300, 600, 1200]) {
        await page.waitForTimeout(delay);
        samples.push({ delayMs: delay, ...(await readState()) });
      }

      results.liveRegionDeepCheck = { beforeIncrement, samplesAfterIncrementClick: samples };
      log('LIVE REGION DEEP CHECK — before increment, then sampled at increasing delays after click', results.liveRegionDeepCheck);

      // Now decrement twice (back to 1, then to 0) and check whether status text ever changes at all,
      // at any point, across the whole value range.
      const decButton = page.getByRole('button', { name: /Decrement Quantity/i });
      const afterDecrements = [];
      for (let i = 0; i < 3; i++) {
        await decButton.click();
        await page.waitForTimeout(300);
        afterDecrements.push(await readState());
      }
      results.liveRegionAcrossDecrements = afterDecrements;
      log('LIVE REGION — status text across 3 decrement clicks (value should go 2->1->0->0)', afterDecrements);

      await page.close();
    } catch (err) {
      results.liveRegion_error = String(err && err.stack ? err.stack : err);
      log('LIVE REGION DEEP CHECK ERROR', results.liveRegion_error);
    }

    // =====================================================================
    // TASK 7 — Orphaned ZimmQuantityStepper: repeat measurements 2-5
    // =====================================================================
    try {
      const url = iframeUrl('commerce-zimmquantitystepper--default');

      // Baseline (unfocused) — explicit blur first, since this story's play() ends on a real
      // click and leaves the Decrease button focused after settling.
      const basePage = await browser.newPage();
      await basePage.goto(url, { waitUntil: 'domcontentloaded' });
      await waitForStorybookRoot(basePage);
      await basePage.waitForTimeout(2000); // let play() (click inc, click dec) fully settle
      const focusBeforeBlur = await getFocusedInfo(basePage);
      await basePage.evaluate(() => document.activeElement && document.activeElement.blur());

      const incLoc = basePage.getByRole('button', { name: 'Increase quantity' });
      const decLoc = basePage.getByRole('button', { name: 'Decrease quantity' });
      const quantitySpan = basePage.locator('span[aria-live="polite"]');

      const baseline = {
        focusResidualFromPlayBeforeBlur: focusBeforeBlur,
        incrementFound: await incLoc.count(),
        decrementFound: await decLoc.count(),
        incrementBaselineStyle: await getLocatorStyle(incLoc.first()),
        decrementBaselineStyle: await getLocatorStyle(decLoc.first()),
        incrementBox: await incLoc.first().boundingBox(),
        decrementBox: await decLoc.first().boundingBox(),
        quantityDisplayedAfterSettle: await quantitySpan.first().textContent(),
      };
      results.task7_baseline = baseline;
      log('TASK 7 — Orphaned ZimmQuantityStepper baseline (unfocused, post-blur) styles + geometry', baseline);
      await basePage.close();

      // Real-tab-focused styles for both buttons (separate fresh loads, settle, then real Tabs)
      async function findTabIndexTo(predicate, cap = 15) {
        const p = await browser.newPage();
        await p.goto(url, { waitUntil: 'domcontentloaded' });
        await waitForStorybookRoot(p);
        await p.waitForTimeout(2000);
        await p.evaluate(() => document.activeElement && document.activeElement.blur());
        for (let i = 1; i <= cap; i++) {
          await p.keyboard.press('Tab');
          const info = await getFocusedInfo(p);
          if (predicate(info)) {
            const style = await getActiveElementStyle(p);
            await p.close();
            return { index: i, info, focusedStyle: style };
          }
        }
        await p.close();
        return { index: -1 };
      }
      const incFocused = await findTabIndexTo((info) => info.name === 'Increase quantity');
      const decFocused = await findTabIndexTo((info) => info.name === 'Decrease quantity');
      results.task7_increment_focused = incFocused;
      results.task7_decrement_focused = decFocused;
      log('TASK 7 — Increase quantity: real Tab index (from blurred state) + focused style', incFocused);
      log('TASK 7 — Decrease quantity: real Tab index (from blurred state) + focused style', decFocused);

      // Keyboard operability + boundary, one continuous session
      const page = await browser.newPage();
      await page.goto(url, { waitUntil: 'domcontentloaded' });
      await waitForStorybookRoot(page);
      await page.waitForTimeout(2000);
      await page.evaluate(() => document.activeElement && document.activeElement.blur());

      const qSpan = page.locator('span[aria-live="polite"]');
      const Q0 = await qSpan.first().textContent();

      let incIdx = -1;
      for (let i = 1; i <= 15; i++) {
        await page.keyboard.press('Tab');
        const info = await getFocusedInfo(page);
        if (info.name === 'Increase quantity') { incIdx = i; break; }
      }
      await page.keyboard.press('Enter');
      await page.waitForTimeout(200);
      const Q1 = await qSpan.first().textContent();
      results.task7_keyboard_increment = { tabIndex: incIdx, before: Q0, after: Q1 };
      log('TASK 7 — Enter on Increase quantity (real tab index=' + incIdx + ')', results.task7_keyboard_increment);

      // Find decrease relative to current focus (still on increase after Enter)
      let decRel = null;
      for (let i = 1; i <= 10; i++) {
        await page.keyboard.press('Tab');
        const info = await getFocusedInfo(page);
        if (info.name === 'Decrease quantity') { decRel = { direction: 'forward', steps: i }; break; }
      }
      if (!decRel) {
        for (let i = 0; i < 10; i++) await page.keyboard.press('Shift+Tab');
        for (let i = 1; i <= 10; i++) {
          await page.keyboard.press('Shift+Tab');
          const info = await getFocusedInfo(page);
          if (info.name === 'Decrease quantity') { decRel = { direction: 'backward', steps: i }; break; }
        }
      }
      results.task7_decRelative = decRel;

      const Q_before_dec = await qSpan.first().textContent();
      await page.keyboard.press('Space');
      await page.waitForTimeout(200);
      const Q_after_dec = await qSpan.first().textContent();
      results.task7_keyboard_decrement = { decRel, before: Q_before_dec, after: Q_after_dec };
      log('TASK 7 — Space on Decrease quantity', results.task7_keyboard_decrement);

      // Boundary — keep decrementing (Space), watch for real disabled state. Starting value is
      // whatever Q_after_dec is (should be back to the story's initial arg, quantity=3).
      const boundarySeq = [];
      let last = Q_after_dec;
      let floor = null;
      let floorAt = null;
      for (let i = 1; i <= 6; i++) {
        await page.keyboard.press('Space');
        await page.waitForTimeout(200);
        const valAfter = await qSpan.first().textContent();
        const info = await getFocusedInfo(page); // still focused on decrement button
        boundarySeq.push({
          iteration: i,
          valueBefore: last,
          valueAfter: valAfter,
          disabledAttr: info.disabled,
          ariaDisabled: info.ariaDisabled,
        });
        if (valAfter === last) { floor = valAfter; floorAt = i; break; }
        last = valAfter;
      }
      results.task7_boundarySequence = boundarySeq;
      results.task7_floor = { floor, floorAt };
      log('TASK 7 — Boundary decrement sequence (real keyboard Space presses)', boundarySeq);
      log('TASK 7 — Floor observed', { floor, floorAt });

      if (floor !== null) {
        const outerHTMLAtFloor = await page.evaluate(() => document.activeElement ? document.activeElement.outerHTML : null);
        await page.keyboard.press('Space');
        await page.waitForTimeout(200);
        const valAfterExtra = await qSpan.first().textContent();
        results.task7_disabledAtFloor = { outerHTMLAtFloor, valueBeforeExtraPress: floor, valueAfterExtraPress: valAfterExtra };
        log('TASK 7 — Real disabled state at floor + no-op confirmation', results.task7_disabledAtFloor);
      }

      await page.close();
    } catch (err) {
      results.task7_error = String(err && err.stack ? err.stack : err);
      log('TASK 7 ERROR', results.task7_error);
    }

    // =====================================================================
    // TASK 8 — Placeholder "Edit" secondaryActions button
    // =====================================================================
    try {
      const url = iframeUrl('commerce-productitem--with-warning-message');

      const basePage = await browser.newPage();
      await basePage.goto(url, { waitUntil: 'domcontentloaded' });
      await waitForStorybookRoot(basePage);
      const editLoc = basePage.getByRole('button', { name: 'Edit', exact: true });
      const baseline = {
        found: await editLoc.count(),
        baselineStyle: await getLocatorStyle(editLoc.first()),
        box: await editLoc.first().boundingBox(),
      };
      results.task8_baseline = baseline;
      log('TASK 8 — Edit placeholder button baseline (unfocused) style + geometry', baseline);
      await basePage.close();

      const p = await browser.newPage();
      await p.goto(url, { waitUntil: 'domcontentloaded' });
      await waitForStorybookRoot(p);
      let idx = -1;
      let focusedStyle = null;
      for (let i = 1; i <= 15; i++) {
        await p.keyboard.press('Tab');
        const info = await getFocusedInfo(p);
        if (info.name === 'Edit') { idx = i; focusedStyle = await getActiveElementStyle(p); break; }
      }
      results.task8_focused = { index: idx, focusedStyle };
      log('TASK 8 — Edit button: real Tab index + focused computed style', results.task8_focused);
      await p.close();
    } catch (err) {
      results.task8_error = String(err && err.stack ? err.stack : err);
      log('TASK 8 ERROR', results.task8_error);
    }

    // =====================================================================
    // TASK 9 — ZimmCartDrawer close button
    // =====================================================================
    try {
      const url = iframeUrl('commerce-zimmcartdrawer--default');

      const basePage = await browser.newPage();
      await basePage.goto(url, { waitUntil: 'domcontentloaded' });
      await waitForStorybookRoot(basePage);
      await basePage.waitForSelector('[role="dialog"]', { timeout: 15000 });
      await basePage.waitForTimeout(300);

      const focusOnOpen = await getFocusedInfo(basePage); // Chakra's own auto-focus behaviour, observed not assumed
      await basePage.evaluate(() => document.activeElement && document.activeElement.blur());

      const dialogButtons = basePage.locator('[role="dialog"] button');
      const buttonCount = await dialogButtons.count();
      const allNames = [];
      for (let i = 0; i < buttonCount; i++) {
        allNames.push(await dialogButtons.nth(i).evaluate((el) => el.getAttribute('aria-label') || el.textContent.trim()));
      }

      const closeLoc = basePage.locator('[role="dialog"] button[aria-label="Close" i]');
      const closeCount = await closeLoc.count();
      const baseline = {
        focusOnDialogOpenBeforeBlur: focusOnOpen,
        totalButtonsInDialog: buttonCount,
        allButtonAccessibleNames: allNames,
        closeButtonFoundByAriaLabel: closeCount,
        closeBaselineStyle: closeCount ? await getLocatorStyle(closeLoc.first()) : null,
        closeBox: closeCount ? await closeLoc.first().boundingBox() : null,
      };
      results.task9_baseline = baseline;
      log('TASK 9 — ZimmCartDrawer dialog buttons + Close button baseline style/geometry', baseline);
      await basePage.close();

      if (closeCount) {
        const p = await browser.newPage();
        await p.goto(url, { waitUntil: 'domcontentloaded' });
        await waitForStorybookRoot(p);
        await p.waitForSelector('[role="dialog"]', { timeout: 15000 });
        await p.waitForTimeout(300);
        await p.evaluate(() => document.activeElement && document.activeElement.blur());
        let idx = -1;
        let focusedStyle = null;
        let info = null;
        for (let i = 1; i <= 15; i++) {
          await p.keyboard.press('Tab');
          info = await getFocusedInfo(p);
          if (/close/i.test(info.name || '')) { idx = i; focusedStyle = await getActiveElementStyle(p); break; }
        }
        results.task9_focused = { index: idx, info, focusedStyle };
        log('TASK 9 — Close button: real Tab index + focused computed style', results.task9_focused);
        await p.close();
      }
    } catch (err) {
      results.task9_error = String(err && err.stack ? err.stack : err);
      log('TASK 9 ERROR', results.task9_error);
    }

    require('fs').writeFileSync(
      '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/6017b702-06fb-4295-9164-1c708495531a/scratchpad/a11y-results-part2.json',
      JSON.stringify(results, null, 2)
    );
    console.log('\n\n=== PART 2 DONE ===');
  } finally {
    await browser.close();
  }
}

main().catch((err) => {
  console.error('FATAL', err);
  process.exit(1);
});

