'use strict';
const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright');
const url = 'http://localhost:6006/iframe.html?id=commerce-productitem--with-warning-message&viewMode=story';

async function waitReady(page) {
  await page.waitForFunction(() => document.querySelector('#storybook-root')?.children.length > 0, { timeout: 15000 });
  await page.waitForTimeout(300);
}

async function readButtons(page) {
  return page.evaluate(() => {
    const inc = document.querySelector('[data-testid="quantity-increment"]');
    const dec = document.querySelector('[data-testid="quantity-decrement"]');
    const input = document.querySelector('input');
    return {
      value: input ? input.value : null,
      incAriaDisabled: inc ? inc.getAttribute('aria-disabled') : null,
      incDisabledProp: inc ? inc.disabled : null,
      decAriaDisabled: dec ? dec.getAttribute('aria-disabled') : null,
      decDisabledProp: dec ? dec.disabled : null,
    };
  });
}

async function main() {
  const browser = await chromium.launch({ headless: true });

  console.log('=== TEST A: fresh load, ONE mouse click on increment, read immediately + after 500ms ===');
  {
    const page = await browser.newPage();
    await page.goto(url, { waitUntil: 'domcontentloaded' });
    await waitReady(page);
    console.log('before click:', JSON.stringify(await readButtons(page)));
    await page.locator('[data-testid="quantity-increment"]').click();
    console.log('immediately after click:', JSON.stringify(await readButtons(page)));
    await page.waitForTimeout(500);
    console.log('500ms after click:', JSON.stringify(await readButtons(page)));
    await page.close();
  }

  console.log('\n=== TEST B: fresh load, Tab to increment + keyboard Enter, read immediately ===');
  {
    const page = await browser.newPage();
    await page.goto(url, { waitUntil: 'domcontentloaded' });
    await waitReady(page);
    console.log('before:', JSON.stringify(await readButtons(page)));
    // Tab sequence from part1: press 1=link, 2=decrement, 3=input, 4=increment
    for (let i = 0; i < 4; i++) await page.keyboard.press('Tab');
    const focusedName = await page.evaluate(() => document.activeElement?.getAttribute('data-testid'));
    console.log('focused element data-testid after 4 tabs:', focusedName);
    await page.keyboard.press('Enter');
    console.log('immediately after Enter:', JSON.stringify(await readButtons(page)));
    await page.waitForTimeout(500);
    console.log('500ms after Enter:', JSON.stringify(await readButtons(page)));
